import React from "react";
import Select from "react-select";

// Generic searchable multi-select dropdown. Selections are combined with OR
// logic by the caller (an item matches if it has ANY of the selected values).
function MultiSelectFilter({ label, options, selected, onChange, placeholder }) {
  const selectOptions = options
    .filter((option) => option && option.trim() !== "")
    .map((option) => ({ value: option, label: option }));

  const value = selected.map((item) => ({ value: item, label: item }));

  return (
    <div className="multi-select-filter">
      {label && <label className="multi-select-label">{label}</label>}
      <Select
        isMulti
        options={selectOptions}
        value={value}
        onChange={(chosen) => onChange((chosen || []).map((item) => item.value))}
        placeholder={placeholder || `Search ${label || "options"}...`}
        classNamePrefix="msf"
        closeMenuOnSelect={false}
      />
    </div>
  );
}

export default MultiSelectFilter;
