import React, { useEffect, useState } from "react";
import Lightbox from "yet-another-react-lightbox";
import "yet-another-react-lightbox/styles.css";

// Amplified single-image viewer used instead of linking out to the raw flyer
// file. Only ever shown one image at a time, so no carousel/navigation
// controls are rendered. Orientation relies on the browser's native EXIF
// handling; a manual rotate button covers the rare image that still needs it.
function EventLightbox({ events, index, onClose }) {
  const [rotation, setRotation] = useState(0);

  useEffect(() => {
    setRotation(0);
  }, [index, events]);

  if (index === null || index === undefined) return null;

  const slides = events.map((event) => ({
    src: event.imageUrl,
    title: event.eventTitle,
    description: event.eventVenue,
  }));

  return (
    <Lightbox
      open={index !== null}
      close={onClose}
      index={index}
      slides={slides}
      render={{
        buttonPrev: () => null,
        buttonNext: () => null,
        slide: ({ slide }) => (
          <img
            src={slide.src}
            alt={slide.title || "Event flyer"}
            style={{
              maxWidth: "90vw",
              maxHeight: "90vh",
              imageOrientation: "from-image",
              transform: `rotate(${rotation}deg)`,
            }}
          />
        ),
      }}
      toolbar={{
        buttons: [
          <button
            key="rotate"
            type="button"
            className="yarl__button"
            title="Rotate if the image looks sideways"
            onClick={() => setRotation((prev) => (prev + 90) % 360)}
          >
            ⟳ Rotate
          </button>,
          "close",
        ],
      }}
    />
  );
}

export default EventLightbox;
